module zebra_max (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] actual_length,\n    input [15:0] string_in,\n    output reg [4:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] NEXT = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n    \n    reg [1:0] state;\n    reg [4:0] i;\n    reg [3:0] idx;\n    reg [4:0] run_reg;\n    reg [4:0] max_run_reg;\n    reg prev_char;\n    reg [15:0] string_storage;\n    reg [3:0] n;\n    wire [3:0] next_idx;\n    wire next_char;\n\n    assign next_idx = (idx == (n - 4'd1)) ? 4'd0 : (idx + 4'd1);\n    assign next_char = string_storage[next_idx];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 5'd0;\n            i <= 5'd0;\n            idx <= 4'd0;\n            run_reg <= 5'd0;\n            max_run_reg <= 5'd0;\n            prev_char <= 1'b0;\n            string_storage <= 16'd0;\n            n <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        if (actual_length == 4'd0) begin\n                            result <= 5'd0;\n                            done <= 1'b1;\n                            state <= DONE_STATE;\n                        end else begin\n                            n <= actual_length;\n                            string_storage <= string_in;\n                            i <= 5'd0;\n                            idx <= 4'd0;\n                            run_reg <= 5'd1;\n                            max_run_reg <= 5'd1;\n                            prev_char <= string_in[0];\n                            state <= NEXT;\n                        end\n                    end\n                end\n                \n                NEXT: begin\n                    if (next_char != prev_char) begin\n                        if (run_reg < {1'b0, n}) run_reg <= run_reg + 5'd1;\n                        else run_reg <= {1'b0, n};\n                        \n                        if ((run_reg + 5'd1) > max_run_reg) begin\n                            max_run_reg <= (run_reg < {1'b0, n}) ? (run_reg + 5'd1) : {1'b0, n};\n                        end\n                    end else begin\n                        run_reg <= 5'd1;\n                    end\n                    \n                    prev_char <= next_char;\n                    idx <= next_idx;\n                    i <= i + 5'd1;\n                    \n                    if (i == (({1'b0, n} * 5'd2) - 5'd2)) begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    result <= (max_run_reg > {1'b0, n}) ? {1'b0, n} : max_run_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule